    cand_rows={r for r in {i for i,j in ones} if {(r,j) for j in range(W)} & ones == {(r,j) for j in [min(j for i,j in ones if i==r), max(j for i,j in ones if i==r)]}}
    cand_cols={c for c in {j for i,j in ones} if {(i,c) for i in range(H)} & ones == {(i,c) for i in [min(i for i,j in ones if j==c), max(i for i,j in ones if j==c)]}}
    # simpler: row has ones at both its min and max column -> full line candidate; require those extremes equal min/max of that row's ones only
