    for r in sorted({i for i,j in ones}):
        js=[j for i,j in ones if i==r]; mn,mx=min(js),max(js)
        if len(set(js))==mx-mn+1: rows.append(r)
    cols=[]
    for c in sorted({j for i,j in ones}):
        is_=[i for i,j in ones if j==c]; mn,mx=min(is_),max(is_)
        if len(set(is_))==mx-mn+1: cols.append(c)
    line={(r,c) for r in rows for c in range(W)}|{(r,c) for c in cols for r in range(H)}
